// A coordinate of this session's own, not a fixed one. Dispatch gives an order to the NEAREST free rider, and a
// development stack keeps every rider that earlier runs registered at the old spot (57 at the time of writing), so a
// fixed location handed the order to somebody else's rider and the saga folders stalled on a 403. Riders more than
// the search radius away are never candidates.
pm.collectionVariables.set("rest_lat", (10 + Math.random() * 40).toFixed(4));

{ const events = pm.response.text().split("\n").filter(l => l.startsWith("data: ")).map(l => JSON.parse(l.slice(6))); const streamed = events.map(e => e.token).join(''); const last = events[events.length - 1] || {};
pm.visualizer.set(`
<style>body{font-family:-apple-system,Segoe UI,sans-serif;padding:14px;max-width:760px} .box{border-left:4px solid #2e7d32;background:#f4f9f4;padding:10px 14px;margin:8px 0;white-space:pre-wrap}
.bad{border-color:#c62828;background:#fdf3f3} .meta{color:#555;font-size:12px} b.tag{background:#eee;border-radius:3px;padding:1px 6px;margin-right:4px}</style>
<div class="meta"><b class="tag">intent: {{intent}}</b><b class="tag">grounded: {{grounded}}</b><b class="tag">chunks: {{chunks}}</b></div>
<div class="box {{#unless grounded}}bad{{/unless}}"><b>What streamed:</b>\n{{streamed}}</div>
{{#if replacement}}<div class="box"><b>Replacement the client shows instead:</b>\n{{replacement}}</div>{{/if}}
{{#if error}}<div class="box bad"><b>Error:</b> {{error}}</div>{{/if}}`,
{ intent: last.intent, grounded: last.grounded, chunks: events.length, streamed: streamed, replacement: last.replacement, error: last.error }); }

